using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
builder.Services.AddSingleton(new TicketClassifierService(dataPath));

var app = builder.Build();

app.MapPost("/api/tickets/classify", (TicketRequest request, TicketClassifierService service) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject and Description are required.");

    if (request.Priority < 1 || request.Priority > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var prediction = service.Predict(request);
    return Results.Ok(prediction);
});

app.MapGet("/api/tickets/metrics", (TicketClassifierService service) =>
{
    return Results.Ok(service.GetMetrics());
});

app.Run();

